WITH valid AS (SELECT id, method, amount, paid_at, status, DAY(paid_at) AS paid_at_day, COALESCE(method, 'UNKNOWN') AS method_filled FROM payments WHERE method IS NOT DISTINCT FROM 'bank_transfer'), flagged AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC) > INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM valid), sessions_payments AS (SELECT id, amount, paid_at, status, paid_at_day, method_filled, SUM(new_group_flag) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT CASE WHEN amount >= 1230 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, DATE_TRUNC('WEEK', paid_at) AS week_start, MAX(paid_at) AS last_paid_at, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, STDDEV_SAMP(amount) AS amount_stddev, SORT_ARRAY(COLLECT_SET(status)) AS status_list, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END), 0), 2) AS amount_per_success, MAX(paid_at) AS last_seen FROM sessions_payments GROUP BY CASE WHEN amount >= 1230 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('WEEK', paid_at)
